module table_counter (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [31:0] A,\n    input wire [31:0] B,\n    output reg [31:0] result,\n    output reg done\n);\n    parameter MAX_ROWS = 200;\n    parameter MAX_STEPS = 20;\n    parameter DATA_WIDTH = 32;\n    \n    localparam [2:0] S_IDLE      = 3'd0;\n    localparam [2:0] S_INIT_ROW  = 3'd1;\n    localparam [2:0] S_CHECK     = 3'd2;\n    localparam [2:0] S_GEN_NEXT  = 3'd3;\n    localparam [2:0] S_FINISH    = 3'd4;\n    \n    reg [2:0] state;\n    reg [DATA_WIDTH-1:0] row_idx;\n    reg [DATA_WIDTH-1:0] current_val;\n    reg [DATA_WIDTH-1:0] count_acc;\n    reg [5:0] step_count;\n    \n    function [31:0] rev;\n        input [31:0] x;\n        reg [31:0] r, t;\n        integer j;\n        reg done_flag;\n        begin\n            r = 32'd0;\n            t = x;\n            done_flag = 1'b0;\n            for (j = 0; j < 10; j = j + 1) begin\n                if (!done_flag) begin\n                    if (t == 32'd0) begin\n                        done_flag = 1'b1;\n                    end else begin\n                        r = (r * 32'd10) + (t % 32'd10);\n                        t = t / 32'd10;\n                    end\n                end\n            end\n            rev = r;\n        end\n    endfunction\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= S_IDLE;\n            row_idx <= 32'd1;\n            current_val <= 32'd0;\n            count_acc <= 32'd0;\n            step_count <= 6'd0;\n            done <= 1'b0;\n            result <= 32'd0;\n        end else begin\n            case (state)\n                S_IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        row_idx <= 32'd1;\n                        count_acc <= 32'd0;\n                        state <= S_INIT_ROW;\n                    end\n                end\n                \n                S_INIT_ROW: begin\n                    step_count <= 6'd0;\n                    if ((row_idx > B) || (row_idx > MAX_ROWS)) begin\n                        state <= S_FINISH;\n                        result <= count_acc;\n                        done <= 1'b1;\n                    end else begin\n                        current_val <= row_idx;\n                        state <= S_CHECK;\n                    end\n                end\n                \n                S_CHECK: begin\n                    if ((current_val >= A) && (current_val <= B))\n                        count_acc <= count_acc + 32'd1;\n                    step_count <= step_count + 6'd1;\n                    state <= S_GEN_NEXT;\n                end\n                \n                S_GEN_NEXT: begin\n                    current_val <= current_val + rev(current_val);\n                    if ((current_val > B) || (step_count >= MAX_STEPS)) begin\n                        row_idx <= row_idx + 32'd1;\n                        state <= S_INIT_ROW;\n                    end else begin\n                        state <= S_CHECK;\n                    end\n                end\n                \n                S_FINISH: begin\n                    if (!start) begin\n                        state <= S_IDLE;\n                        done <= 1'b0;\n                    end\n                end\n                \n                default: state <= S_IDLE;\n            endcase\n        end\n    end\nendmodule